827b65bc (John Smathers   2026-07-15 03:40:14 -0400 35) /// [`MAX_SESSION_TODOS`] entries. When the map is at or above the bound and a
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 36) /// new session is requested, the least-recently-touched **empty** entry is
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 37) /// evicted — a session that still holds confirmed todo items is never silently
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 38) /// dropped. If every resident entry is non-empty the map grows temporarily;
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 39) /// once empty entries become available, the next insert reclaims them. This
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 40) /// guarantees the TUI tray cannot display a non-empty projection while the
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 41) /// corresponding daemon tool has been evicted.
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 42) #[derive(Default)]
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 43) struct SessionTodos {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 44)     next_touch: u64,
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 45)     tools: std::collections::HashMap<String, (u64, Arc<crate::tools::todo::TodoTool>)>,
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 46) }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 47) 
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 48) impl SessionTodos {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 49)     fn get_or_insert(&mut self, session_id: &str) -> Arc<crate::tools::todo::TodoTool> {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 50)         let touch = self.next_touch;
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 51)         self.next_touch = self.next_touch.wrapping_add(1);
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 52)         if let Some((last_touch, tool)) = self.tools.get_mut(session_id) {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 53)             *last_touch = touch;
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 54)             return tool.clone();
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 55)         }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 56)         // Soft bound: repeatedly evict the least-recently-touched *empty*
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 57)         // tools until we're under the bound or no empty candidate remains.
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 58)         // Non-empty entries are pinned; if all are non-empty the map can
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 59)         // grow temporarily.
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 60)         while self.tools.len() >= MAX_SESSION_TODOS {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 61)             let candidate = self
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 62)                 .tools
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 63)                 .iter()
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 64)                 .filter(|(_, (_, tool))| tool.is_empty())
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 65)                 .min_by_key(|(_, (last_touch, _))| *last_touch)
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 66)                 .map(|(id, _)| id.clone());
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 67)             match candidate {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 68)                 Some(oldest) => {
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 69)                     self.tools.remove(&oldest);
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 70)                 }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 71)                 None => break,
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 72)             }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 73)         }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 74)         let tool: Arc<crate::tools::todo::TodoTool> = Arc::new(crate::tools::todo::TodoTool::new());
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 75)         self.tools
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 76)             .insert(session_id.to_string(), (touch, tool.clone()));
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 77)         tool
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 78)     }
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 79) }
