827b65bc (John Smathers   2026-07-15 03:40:14 -0400 76)             .insert(session_id.to_string(), (touch, tool.clone()));
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 77)         tool
827b65bc (John Smathers   2026-07-15 03:40:14 -0400 78)     }
